/**
 * Every image on the site, in one map.
 *
 * Entries with a local "/photos/…" src are the client's own workroom
 * photography (re-encoded, EXIF stripped). Entries still using `u(…)` are
 * licensed Unsplash stock placeholders, chosen against the imagery rules in
 * the plan (2.4) — swap them out the same way as new photos arrive. Curtain,
 * campervan, upholstery and garment slots are now real (the garment photos
 * are the client's previous factory, supplied with consent — faces may show).
 * Still stock: the curtain-range tiles, fabric close-ups and the area pages.
 *
 * GRADE is applied to every remote image so stock from different photographers
 * reads as one consistent brand. Local photos are left ungraded.
 */

export type Img = {
  src: string;
  alt: string;
  /** Tiny inline JPEG used as the blur-up placeholder. */
  blurDataURL: string;
};

/** Slight desaturation, a touch of lift, softened contrast. */
const GRADE = "sat=-12&bri=4&con=-3";

const u = (id: string, w: number) =>
  `https://images.unsplash.com/${id}?auto=format&fit=crop&q=80&w=${w}&${GRADE}`;

